  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$La leçon 1 pose la règle : une objection est une information, on la reformule et on la fait valider avant d'y répondre. Répondre tout de suite, c'est répondre à la question que l'on croit avoir entendue. Négocier ou éviter le sujet ne traite pas la question posée.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q02$academy_seed$, $academy_seed$vrai_faux$academy_seed$, $academy_seed$Reformuler une objection$academy_seed$, $academy_seed$Vrai ou faux : une fois l'objection reformulée, le conseiller peut répondre sans attendre que le client confirme la reformulation, pour ne pas ralentir le rendez-vous.$academy_seed$, $academy_seed$["Vrai","Faux"]$academy_seed$::jsonb, 1)
