  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Faux. La leçon 1 impose de faire valider la reformulation par le client (« C'est bien cela ? ») puis de poser une question de précision avant toute réponse. Répondre avant la confirmation, c'est répondre à la question que l'on croit avoir entendue.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q03$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$Reformuler une objection$academy_seed$, $academy_seed$Cas fictif. Une cliente dit : « Je ne veux pas payer quelqu'un qui me mettra sur un fonds sans regarder ma situation. » Quelle reformulation est fidèle ?$academy_seed$, $academy_seed$["« Vous trouvez que nos frais sont trop élevés par rapport à une banque en ligne, c'est cela ? »","« Si je comprends bien, ce qui vous inquiète, c'est de payer pour un conseil qui ne tiendrait pas compte de votre situation. C'est bien cela ? »","« Vous voulez donc un conseil sur-mesure, ce que nous faisons justement, n'est-ce pas ? »","« Vous avez eu une mauvaise expérience avec un conseiller par le passé, je suppose ? »"]$academy_seed$::jsonb, 2)
