  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La leçon 1 distingue la reformulation fidèle, qui reprend les mots du client et demande validation, de la reformulation qui déforme (le prix, alors qu'elle parle de valeur), qui oriente (une réponse déguisée) ou qui suppose un vécu que la cliente n'a pas évoqué.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q04$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Reformuler une objection$academy_seed$, $academy_seed$Cas fictif. Après votre reformulation, le client confirme : « Oui, je peux le faire seul sur une plateforme. » Quelle question de précision posez-vous ensuite ?$academy_seed$, $academy_seed$["« Concrètement, que feriez-vous seul, et sur quel horizon ? »","« Savez-vous que les plateformes ont aussi des frais cachés ? »","« Préférez-vous que je vous fasse une remise sur les frais ? »","« Avez-vous déjà lu un document d'informations clés en entier ? »"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$La leçon 1 prévoit, après validation de la reformulation, une seule question ouverte de précision qui fait parler le client de ce qu'il ferait réellement. Les autres options contre-argumentent, négocient ou mettent le client en défaut avant d'avoir compris son projet.$academy_seed$);
